/**
 * DW-57 browser integration: actual navigation while Refresh/Retry owns both
 * pending events GETs, shared-store settlement, remount recovery, native focus.
 * Zero post-unmount React setter calls are proved by the component lifetime
 * suite; browser silence cannot observe those calls because React discards them.
 */
import type { Page } from '@playwright/test';
import { log } from '@seontechnologies/playwright-utils';
import { recurse } from '@seontechnologies/playwright-utils/recurse';
import { test, expect } from '../../support/merged-fixtures';
import type { EventsRefreshControl } from '../../support/fixtures/events-refresh-control';
import { navigateTo } from '../../support/helpers/navigation';

const expectedLoadFailure = { annotation: [{ type: 'skipNetworkMonitoring' }] };

async function eventsSnapshot(page: Page) {
  return page.evaluate(() => {
    const state = window.__APP_STORE__!.getState();
    return {
      ids: state.events.map((event) => event.id).sort(),
      loading: state.eventsIsLoading,
      error: state.eventsError,
      view: state.currentView,
    };
  });
}

async function openSettings(page: Page, control: EventsRefreshControl) {
  await page.goto('/settings');
  // Two loads (four GETs) on first mount under the app's real StrictMode.
  await control.waitForIdle();
  await expect(page.getByTestId('settings-view')).toBeVisible();
  await expect(page.getByTestId('events-settings-loading')).toHaveCount(0);
  await expect(page.getByTestId('events-settings-load-region')).toHaveAttribute('aria-busy', 'false');
}

async function openFailedSettings(page: Page, control: EventsRefreshControl) {
  const initialLoad = control.holdNextLoad('failure');
  await page.goto('/settings');
  await initialLoad.waitForPending(2);
  initialLoad.release();
  expect(await initialLoad.waitForCompleted()).toEqual([503, 503, 503, 503]);
  await control.waitForIdle();
  await expect(page.getByTestId('events-settings-load-error')).toBeVisible();
  await expect(page.getByRole('button', { name: 'Retry', exact: true })).toBeEnabled();
}

async function leaveForMood(page: Page) {
  // Home also calls loadEvents and could supersede the pending load under test.
  await navigateTo(page, 'mood');
  await expect(page.getByTestId('mood-tracker')).toBeVisible();
  await expect(page.getByTestId('events-settings')).toHaveCount(0);
  await page.getByRole('button', { name: 'Happy mood', exact: true }).focus();
}

async function expectSettledOnMood(page: Page, ids: string[], failed: boolean) {
  await recurse(
    () => eventsSnapshot(page),
    (state) => {
      expect(state.loading).toBe(false);
      expect(state.ids).toEqual([...ids].sort());
      if (failed) expect(state.error).toBeTruthy();
      else expect(state.error).toBeNull();
      expect(state.view).toBe('mood');
    },
    { timeout: 15000, interval: 50, log: 'Waiting for shared events store after Settings unmount' }
  );
  await expect(page.getByTestId('mood-tracker')).toBeVisible();
  await expect(page.getByRole('button', { name: 'Happy mood', exact: true })).toBeFocused();
  await expect(page.getByTestId('events-settings-load-error')).toHaveCount(0);
}

async function returnToRecoveredSettings(page: Page, witnessId: string, missingId?: string) {
  await navigateTo(page, 'settings');
  await recurse(
    () => eventsSnapshot(page),
    (state) => !state.loading && state.error === null &&
      state.ids.includes(witnessId) && (!missingId || !state.ids.includes(missingId)),
    { timeout: 15000, interval: 50, log: 'Waiting for fresh Settings mount recovery' }
  );
  await expect(page.getByTestId(`event-row-${witnessId}`)).toBeVisible();
  if (missingId) await expect(page.getByTestId(`event-row-${missingId}`)).toHaveCount(0);
  await expect(page.getByTestId('events-settings-load-error')).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Add event', exact: true })).toBeEnabled();
}

test.beforeEach(async ({ page }) => {
  await page.addInitScript(() => {
    localStorage.setItem('lastWelcomeView', Date.now().toString());
  });
});

test.describe('DW-57 events refresh and retry across Settings unmount', () => {
  test('[P1] DW57-E2E-001 stale edit refresh succeeds after navigating to Mood', async ({
    page, coupleEvents, eventsRefreshControl, apiRequest, authToken, interceptNetworkCall,
  }) => {
    const [stale, witness] = await coupleEvents.seed([
      { label: 'DW57 stale edit', dayOffset: 14 },
      { label: 'DW57 edit survivor', dayOffset: -14 },
    ]);
    await log.step('Open a creator event, then remove its server row outside the stale UI');
    await openSettings(page, eventsRefreshControl);
    await expect(page.getByTestId(`event-row-${stale.id}`)).toBeVisible();
    const removed = await apiRequest({
      method: 'DELETE', baseUrl: process.env.SUPABASE_URL,
      path: `/rest/v1/events?id=eq.${stale.id}`,
      headers: { apikey: process.env.SUPABASE_ANON_KEY!, Authorization: `Bearer ${authToken}` },
    });
    expect(removed.status).toBe(204);
    const rejectedWrite = interceptNetworkCall({ method: 'PATCH', url: '**/rest/v1/events*' });
    await page.getByTestId(`event-edit-${stale.id}`).click();
    await page.getByTestId('events-form-label').fill('DW57 attempted stale edit');
    await page.getByRole('button', { name: 'Update', exact: true }).click();
    const rejected = await rejectedWrite;
    expect(rejected.status).toBe(200);
    expect(rejected.responseJson).toEqual([]);
    await expect(page.getByTestId('events-form-error')).toContainText('Event not found or not yours to edit');

    await log.step('Hold both Refresh reads, then unmount Settings through navigation');
    const refresh = eventsRefreshControl.holdNextLoad('success');
    await page.getByRole('button', { name: 'Refresh events', exact: true }).click();
    await refresh.waitForPending();
    await expect(page.getByTestId('events-form')).toHaveCount(0);
    await leaveForMood(page);
    refresh.release();
    expect(await refresh.waitForCompleted()).toEqual([200, 200]);
    await expectSettledOnMood(page, [witness.id], false);
    await returnToRecoveredSettings(page, witness.id, stale.id);
  });

  test('[P1] DW57-E2E-002 stale delete refresh fails after navigating to Mood', expectedLoadFailure, async ({
    page, coupleEvents, eventsRefreshControl, apiRequest, authToken, interceptNetworkCall,
  }) => {
    const [stale, witness] = await coupleEvents.seed([
      { label: 'DW57 stale delete', dayOffset: 14 },
      { label: 'DW57 delete survivor', dayOffset: -14 },
    ]);
    await log.step('Keep a stale creator row rendered after an actual server deletion');
    await openSettings(page, eventsRefreshControl);
    await expect(page.getByTestId(`event-row-${stale.id}`)).toBeVisible();
    const removed = await apiRequest({
      method: 'DELETE', baseUrl: process.env.SUPABASE_URL,
      path: `/rest/v1/events?id=eq.${stale.id}`,
      headers: { apikey: process.env.SUPABASE_ANON_KEY!, Authorization: `Bearer ${authToken}` },
    });
    expect(removed.status).toBe(204);
    const rejectedWrite = interceptNetworkCall({ method: 'DELETE', url: '**/rest/v1/events*' });
    await page.getByTestId(`event-delete-${stale.id}`).click();
    await page.getByTestId('events-delete-confirm').click();
    const rejected = await rejectedWrite;
    expect(rejected.status).toBe(200);
    expect(rejected.responseJson).toEqual([]);
    await expect(page.getByTestId('events-delete-error')).toContainText('Event not found or not yours to delete');

    await log.step('Let a failed Refresh settle after Settings has unmounted');
    const refresh = eventsRefreshControl.holdNextLoad('failure');
    await page.getByRole('button', { name: 'Refresh events', exact: true }).click();
    await refresh.waitForPending();
    await expect(page.getByTestId('events-delete-confirmation')).toHaveCount(0);
    await leaveForMood(page);
    refresh.release();
    expect(await refresh.waitForCompleted()).toEqual([503, 503]);
    await expectSettledOnMood(page, [stale.id, witness.id], true);
    await returnToRecoveredSettings(page, witness.id, stale.id);
  });

  for (const outcome of ['success', 'failure'] as const) {
    const id = outcome === 'success' ? 'DW57-E2E-003' : 'DW57-E2E-004';
    test(`[P1] ${id} pending Retry settles with ${outcome} after navigating to Mood`, expectedLoadFailure, async ({
      page, coupleEvents, eventsRefreshControl,
    }) => {
      const [witness] = await coupleEvents.seed([{ label: `DW57 retry ${outcome}`, dayOffset: 21 }]);
      await log.step('Fail both initial Settings load windows and expose Retry');
      await openFailedSettings(page, eventsRefreshControl);
      expect((await eventsSnapshot(page)).ids).toEqual([]);

      await log.step(`Hold Retry, unmount Settings, then release its ${outcome} response`);
      const retry = eventsRefreshControl.holdNextLoad(outcome);
      await page.getByRole('button', { name: 'Retry', exact: true }).click();
      await retry.waitForPending();
      await expect(page.getByTestId('events-settings-load-region')).toHaveAttribute('aria-busy', 'true');
      await leaveForMood(page);
      retry.release();
      expect(await retry.waitForCompleted()).toEqual(outcome === 'success' ? [200, 200] : [503, 503]);
      await expectSettledOnMood(page, outcome === 'success' ? [witness.id] : [], outcome === 'failure');
      await returnToRecoveredSettings(page, witness.id);
    });
  }

  test('[P2] DW57-E2E-005 mounted Retry fails then succeeds and restores native focus', expectedLoadFailure, async ({
    page, coupleEvents, eventsRefreshControl,
  }) => {
    const [witness] = await coupleEvents.seed([{ label: 'DW57 mounted retry', dayOffset: 21 }]);
    await log.step('Start from an empty failed load under the app StrictMode');
    await openFailedSettings(page, eventsRefreshControl);

    await log.step('A failed manual Retry restores an enabled, focused Retry control');
    const failure = eventsRefreshControl.holdNextLoad('failure');
    await page.getByRole('button', { name: 'Retry', exact: true }).click();
    await failure.waitForPending();
    await expect(page.getByTestId('events-settings-load-region')).toHaveAttribute('aria-busy', 'true');
    failure.release();
    expect(await failure.waitForCompleted()).toEqual([503, 503]);
    await expect(page.getByTestId('events-settings-load-error')).toBeVisible();
    await expect(page.getByRole('button', { name: 'Retry', exact: true })).toBeEnabled();
    await expect(page.getByRole('button', { name: 'Retry', exact: true })).toBeFocused();

    await log.step('A second Retry recovers the event list and focuses the surviving Add control');
    const recovery = eventsRefreshControl.holdNextLoad('success');
    await page.getByRole('button', { name: 'Retry', exact: true }).click();
    await recovery.waitForPending();
    recovery.release();
    expect(await recovery.waitForCompleted()).toEqual([200, 200]);
    await recurse(
      () => eventsSnapshot(page),
      (state) => !state.loading && state.error === null && state.ids.includes(witness.id),
      { timeout: 15000, interval: 50, log: 'Waiting for mounted Retry store recovery' }
    );
    await expect(page.getByTestId(`event-row-${witness.id}`)).toBeVisible();
    await expect(page.getByTestId('events-settings-load-error')).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'Add event', exact: true })).toBeFocused();
  });
});

infrastructure.content:
import { test as base } from '@playwright/test';
import { interceptNetworkCall } from '@seontechnologies/playwright-utils/intercept-network-call';
import { recurse } from '@seontechnologies/playwright-utils/recurse';

export type EventReadOutcome = 'success' | 'failure';
type EventWindow = 'upcoming' | 'past';

export type EventsRefreshGate = {
  waitForPending: (requestsPerWindow?: number) => Promise<void>;
  release: () => void;
  waitForCompleted: () => Promise<number[]>;
};

export type EventsRefreshControl = {
  holdNextLoad: (outcome: EventReadOutcome) => EventsRefreshGate;
  waitForIdle: (minimumRequestsPerWindow?: number) => Promise<void>;
};

type GateState = {
  outcome: EventReadOutcome;
  arrived: Record<EventWindow, number>;
  completed: number;
  statuses: number[];
  released: boolean;
  release: () => void;
  ready: Promise<void>;
};

/**
 * Owns both GET windows of eventsService.getEvents. Gates are armed before a
 * trigger, and response completion is tracked separately from request arrival:
 * the installed utility's handler promise reports only the first arrival.
 * Success forwards real PostgREST traffic; failure injects a deliberate 503.
 */
export const test = base.extend<{ eventsRefreshControl: EventsRefreshControl }>({
  eventsRefreshControl: async ({ page }, use) => {
    const totals: Record<EventWindow, number> = { upcoming: 0, past: 0 };
    const gates: GateState[] = [];
    const operations: Promise<void>[] = [];
    const errors: unknown[] = [];
    let currentGate: GateState | null = null;
    let pending = 0;

    const checkErrors = () => {
      if (errors.length) throw new AggregateError(errors, 'Events response control failed');
    };

    // Installed before the test navigates. One persistent handler coordinates
    // the parallel upcoming/past queries and StrictMode's mount replay.
    const firstRequest = interceptNetworkCall({
      page,
      method: 'GET',
      url: '**/rest/v1/events*',
      handler: async (route, request) => {
        const dateFilter = new URL(request.url()).searchParams.get('event_date');
        const window: EventWindow | null = dateFilter?.startsWith('gte.')
          ? 'upcoming'
          : dateFilter?.startsWith('lt.')
            ? 'past'
            : null;
        if (!window) {
          await route.continue();
          return;
        }

        const gate = currentGate;
        totals[window] += 1;
        pending += 1;
        if (gate) gate.arrived[window] += 1;

        const operation = (async () => {
          try {
            if (gate) await gate.ready;
            if (gate?.outcome === 'failure') {
              await route.fulfill({
                status: 503,
                contentType: 'application/json',
                body: JSON.stringify({
                  code: 'TEA_EVENTS_LOAD_FAILURE',
                  message: 'TEA forced events refresh failure',
                  details: null,
                  hint: null,
                }),
              });
            } else {
              await route.continue();
            }

            // This is the captured request supplied by interceptNetworkCall,
            // not a second response observer which might miss either window.
            const response = await request.response();
            if (!response) throw new Error('Events GET completed without an HTTP response');
            const responseFailure = await response.finished();
            if (responseFailure) throw responseFailure;
            if (gate) {
              gate.statuses.push(response.status());
              gate.completed += 1;
            }
          } catch (error) {
            errors.push(error);
          } finally {
            pending -= 1;
          }
        })();
        operations.push(operation);
        await operation;
      },
    });
    // Capture setup failure immediately, including when a test fails before
    // its first request. The promise is awaited on successful idle checks.
    void firstRequest.catch((error: unknown) => errors.push(error));

    try {
      await use({
        holdNextLoad: (outcome) => {
          checkErrors();
          if (currentGate) throw new Error('Release the current events gate before arming another');
          let release = () => {};
          const ready = new Promise<void>((resolve) => { release = resolve; });
          const gate: GateState = {
            outcome,
            arrived: { upcoming: 0, past: 0 },
            completed: 0,
            statuses: [],
            released: false,
            release,
            ready,
          };
          gates.push(gate);
          currentGate = gate;

          return {
            waitForPending: async (requestsPerWindow = 1) => {
              await recurse(
                async () => {
                  checkErrors();
                  return { ...gate.arrived, completed: gate.completed };
                },
                (state) => state.upcoming >= requestsPerWindow &&
                  state.past >= requestsPerWindow && state.completed === 0,
                { timeout: 15000, interval: 50, log: 'Waiting for both held events GET windows' }
              );
            },
            release: () => {
              if (gate.released) return;
              gate.released = true;
              if (currentGate === gate) currentGate = null;
              gate.release();
            },
            waitForCompleted: async () => {
              await recurse(
                async () => {
                  checkErrors();
                  return gate.released && gate.completed > 0 &&
                    gate.completed === gate.arrived.upcoming + gate.arrived.past;
                },
                (completed) => completed,
                { timeout: 15000, interval: 50, log: 'Waiting for all released events responses' }
              );
              return [...gate.statuses];
            },
          };
        },
        waitForIdle: async (minimumRequestsPerWindow = 2) => {
          await recurse(
            async () => {
              checkErrors();
              return totals.upcoming >= minimumRequestsPerWindow &&
                totals.past >= minimumRequestsPerWindow && pending === 0;
            },
            (idle) => idle,
            { timeout: 15000, interval: 50, log: 'Waiting for events mount requests to settle' }
          );
          await firstRequest;
        },
      });
    } finally {
      // Drain every held response before the authenticated page/context closes,
      // including when an assertion or navigation fails before explicit release.
      currentGate = null;
      for (const gate of gates) gate.release();
      await Promise.allSettled(operations);
      checkErrors();
    }
  },
});
